def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = my[-1]
    last_opp = op[-1]

    opD = 0
    myD = 0
    for i in range(n):
        if op[i] == 'D':
            opD += 1
        if my[i] == 'D':
            myD += 1

    look = n if n < 12 else 12
    recent_opD = 0
    recent_myD = 0
    for i in range(n - look, n):
        if op[i] == 'D':
            recent_opD += 1
        if my[i] == 'D':
            recent_myD += 1

    forgive = 0
    punish = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                forgive += 1
            else:
                punish += 1

    hard = False
    if n >= 6:
        if opD == n or opD >= n - 1:
            hard = True
        elif opD * 4 >= n * 3 and recent_opD >= 3:
            hard = True
        elif recent_opD >= look - 2 and n >= look:
            hard = True

    if n == 98:
        if hard:
            return 'D'
        if opD * 4 >= n * 3:
            return 'D'
        if opD == 0:
            if last_me == 'D' or forgive >= 1:
                return 'D'
            return 'C'
        if forgive > punish and punish == 0 and recent_opD == 0:
            return 'D'
        return 'C'

    if hard:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if recent_opD >= 4 or opD * 2 > n:
                return 'D'
            return 'C'

        if n >= 2 and my[-2] == 'D':
            if punish <= 1 and opD <= max(2, n // 4) and forgive <= 2:
                return 'C'
            if recent_opD >= 3:
                return 'D'
            return 'C'

        if recent_opD >= 3 or opD * 2 > n:
            return 'D'

        if opD <= 2 and recent_opD <= 1 and myD <= 2 and n >= 4:
            if rng.random() < 0.6:
                return 'C'
            return 'D'

        if opD <= 2 and rng.random() < 0.15:
            return 'C'

        return 'D'

    if n >= 12 and myD > 0:
        if last_me == 'C' and my[-2] == 'D' and forgive > punish and punish <= 1:
            if recent_myD < 10:
                return 'D'

        if last_me == 'D' and forgive >= 2 and punish == 0 and recent_myD < 10:
            return 'D'

    if n == 12 and opD == 0 and myD == 0:
        return 'D'

    if n <= 90 and opD <= 1 and recent_opD == 0 and forgive > punish and rng.random() < 0.01:
        return 'D'

    return 'C'
